package dev.slithergoh.pixelmonradar.client;

import com.pixelmonmod.pixelmon.api.pokemon.Pokemon;import com.pixelmonmod.pixelmon.entities.pixelmon.PixelmonEntity;import net.minecraft.client.Minecraft;import net.minecraft.world.phys.AABB;import java.util.*;
public final class PokemonScanner{private PokemonScanner(){}public static List<PokemonInfo>scan(){Minecraft mc=Minecraft.getInstance();if(mc.level==null||mc.player==null)return List.of();double r=RadarSettings.pokemonRange;AABB box=mc.player.getBoundingBox().inflate(r);List<PokemonInfo>out=new ArrayList<>();for(PixelmonEntity entity:mc.level.getEntitiesOfClass(PixelmonEntity.class,box)){Pokemon p=entity.getPokemon();if(p==null)continue;boolean shiny=p.isShiny(),legendary=p.isLegendary(true),mythical=p.isMythical(),ub=p.isUltraBeast(),paradox=p.isParadox(),boss=entity.isBossPokemon();PokemonInfo info=new PokemonInfo(entity.getId(),entity.getLocalizedName(),p.getPokemonLevel(),mc.player.distanceTo(entity),entity.blockPosition(),p.getSprite(),shiny,legendary,mythical,ub,paradox,boss,String.valueOf(p.getGender()),p.getFormName(),p.getPaletteName(),boss&&entity.getBossTier()!=null?String.valueOf(entity.getBossTier()):"");boolean shinyFilter=RadarSettings.shinyOnly,rareFilter=RadarSettings.rareOnly;if(shinyFilter||rareFilter){boolean matches=(shinyFilter&&shiny)||(rareFilter&&info.rare());if(!matches)continue;}out.add(info);}out.sort(Comparator.comparingDouble(PokemonInfo::distance));return out;}}
